//! 🗺️ Original dictionary coordinates drive an incrementally admitted hash join and patience subsequence.
use crate::LayoutMutation;
use semio_s_artifact_layout_layout_model::snapshot::LayoutSnapshot;
use semio_framework_value_dictionary::QuestionValueEqualityCursor;
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,scratch_hash::ScratchHashMap,retained_clone::{RetainedCloneRef,RetainedCloneBinding,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,retained_clone_grant_admits}};
use std::mem::{ManuallyDrop,size_of};
#[derive(Clone,Copy)]struct Old{to:usize,equal:bool,keep:bool,link:usize}
#[derive(Clone,Copy)]struct New{from:usize,equal:bool}
const NONE:usize=usize::MAX;
const SEED:u64=14695981039346656037;
fn fault()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"data-field plan requires unique original dictionary rows")}
fn add(d:RetirementDemand)->RetirementDemand{RetirementDemand{copy_bytes:d.copy_bytes+DataFieldsPlan::FIXED,depth:d.depth+1,..d}}
fn child(g:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-DataFieldsPlan::FIXED,maximum_depth:g.maximum_depth-1,..g}}
fn paid(mut p:RetainedCloneProgress)->RetainedCloneProgress{p.copied_items=p.copied_items.max(1);p.copied_bytes+=DataFieldsPlan::FIXED;p}
fn failure(e:ValueError)->ValueError{let p=paid(e.retained_progress());e.with_retained_progress(p)}
/// 🧳️ All retained scratch rows contain scalar addresses; original bindings outlive their borrowed comparisons.
pub struct DataFieldsPlan{m:Option<RetainedCloneBinding>,b:Option<RetainedCloneBinding>,old:ManuallyDrop<Vec<Old>>,new:ManuallyDrop<Vec<New>>,tails:ManuallyDrop<Vec<usize>>,map:ManuallyDrop<ScratchHashMap<u64,usize>>,values:QuestionValueEqualityCursor,phase:u8,at:usize,other:usize,offset:usize,slot:usize,hash:u64,lo:usize,hi:usize,kept:usize,closing:bool}
impl Default for DataFieldsPlan{fn default()->Self{Self{m:None,b:None,old:ManuallyDrop::new(Vec::new()),new:ManuallyDrop::new(Vec::new()),tails:ManuallyDrop::new(Vec::new()),map:ManuallyDrop::new(Default::default()),values:Default::default(),phase:0,at:0,other:0,offset:0,slot:0,hash:SEED,lo:0,hi:0,kept:0,closing:false}}}
impl DataFieldsPlan{
 const FIXED:usize=size_of::<Self>()*2+1024;
 pub fn verify(&self,m:RetainedCloneRef<'_,LayoutMutation>,b:RetainedCloneRef<'_,LayoutSnapshot>)->Result<(),ValueError>{m.check_binding(&self.m)?;b.check_binding(&self.b)?;Ok(())}
 pub fn ready(&self)->bool{self.phase==21&&!self.closing}
 pub fn old_len(&self)->usize{self.old.len()}
 pub fn new_len(&self)->usize{self.new.len()}
 pub fn removed(&self,i:usize)->bool{!self.old[i].equal}
 pub fn inserted(&self,i:usize)->bool{!self.new[i].equal}
 pub fn moved(&self,i:usize)->Option<usize>{let r=self.old[i];(r.equal&&!r.keep).then_some(r.to)}
 pub fn removed_count(&self)->usize{self.old.len()-self.kept}
 pub fn inserted_count(&self)->usize{self.new.len()-self.kept}
 pub fn moved_count(&self)->usize{self.kept-self.tails.len()}
 fn fixed()->RetirementDemand{RetirementDemand{copy_bytes:Self::FIXED,depth:1,..Default::default()}}
 fn extents(m:RetainedCloneRef<'_,LayoutMutation>,b:RetainedCloneRef<'_,LayoutSnapshot>)->(usize,usize){let next=super::decision::authored(m).get().as_ref();if let Some(next)=next{(b.get().data_fields.as_ref().map_or(0,|x|x.entries.len()),next.entries.len())}else{(0,0)}}
 fn keys<'a>(&self,m:RetainedCloneRef<'a,LayoutMutation>,b:RetainedCloneRef<'a,LayoutSnapshot>)->(&'a str,&'a str){let new=super::decision::authored(m).get().as_ref().unwrap();let query=if self.phase<=11{&new.entries[self.at].question_id}else{&b.get().data_fields.as_ref().unwrap().entries[self.at].question_id};(query,&new.entries[self.other].question_id)}
 fn value_pair<'a>(&self,m:RetainedCloneRef<'a,LayoutMutation>,b:RetainedCloneRef<'a,LayoutSnapshot>)->(RetainedCloneRef<'a,semio_framework_value::DslValue>,RetainedCloneRef<'a,semio_framework_value::DslValue>){(super::decision::baseline(b).project(self.at,|d|&d.as_ref().unwrap().entries[self.at].value),super::decision::authored(m).project(self.other,|d|&d.as_ref().unwrap().entries[self.other].value))}
 pub fn demand(&self,m:RetainedCloneRef<'_,LayoutMutation>,b:RetainedCloneRef<'_,LayoutSnapshot>,_body:usize)->Result<RetirementDemand,ValueError>{m.check_binding(&self.m)?;b.check_binding(&self.b)?;if self.closing{return Err(fault())}let(old,new)=Self::extents(m,b);Ok(match self.phase{0=>add(m.binding_demand(&self.m)?.unwrap_or_default()),1=>add(b.binding_demand(&self.b)?.unwrap_or_default()),2=>RetirementDemand{capacity_bytes:old.checked_mul(size_of::<Old>()).ok_or_else(fault)?,..Self::fixed()},3=>RetirementDemand{capacity_bytes:new.checked_mul(size_of::<New>()).ok_or_else(fault)?,..Self::fixed()},4=>RetirementDemand{capacity_bytes:old.checked_mul(size_of::<usize>()).ok_or_else(fault)?,..Self::fixed()},5=>add(ScratchHashMap::<u64,usize>::reservation_demands(new)?),15=>{let(a,b)=self.value_pair(m,b);add(self.values.demand(a,b,256)?)},16=>add(self.values.rebind_demand(256)?),_=>Self::fixed()})}
 pub fn advance(&mut self,m:RetainedCloneRef<'_,LayoutMutation>,b:RetainedCloneRef<'_,LayoutSnapshot>,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.demand(m,b,g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}let mut p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};let(old,new)=Self::extents(m,b);match self.phase{
 0=>{p=paid(m.bind(&mut self.m,child(g)).map_err(failure)?.unwrap_or_default());self.phase=1},1=>{p=paid(b.bind(&mut self.b,child(g)).map_err(failure)?.unwrap_or_default());self.phase=2},
 2|3|4=>{let phase=self.phase;self.phase=254;let(failed,capacity)=match phase{2=>(self.old.try_reserve_exact(old).is_err(),self.old.capacity()*size_of::<Old>()),3=>(self.new.try_reserve_exact(new).is_err(),self.new.capacity()*size_of::<New>()),_=>(self.tails.try_reserve_exact(old).is_err(),self.tails.capacity()*size_of::<usize>())};p.retained_capacity_bytes=capacity;if failed||capacity>g.maximum_capacity_bytes{return Err(fault().with_retained_progress(p))}self.phase=phase+1},
 5=>{self.phase=254;*self.map=ScratchHashMap::try_reserve_uninitialized(new).map_err(failure)?;p.retained_capacity_bytes=self.map.backing_bytes();if p.retained_capacity_bytes>g.maximum_capacity_bytes{return Err(fault().with_retained_progress(p))}self.phase=6},
 6=>if self.old.len()<old{self.old.push(Old{to:NONE,equal:false,keep:false,link:NONE})}else{self.phase=7},7=>if self.new.len()<new{self.new.push(New{from:NONE,equal:false})}else{self.phase=8},8=>if !self.map.initialize_one()?{self.phase=9},
 9|12=>{let indexing=self.phase==9;if self.at==if indexing{new}else{old}{self.at=0;self.offset=0;self.hash=SEED;self.phase=if indexing{12}else{17}}else if new==0{self.phase=17;self.at=0}else{let next=super::decision::authored(m).get().as_ref().unwrap();let key=if indexing{&next.entries[self.at].question_id}else{&b.get().data_fields.as_ref().unwrap().entries[self.at].question_id};let end=key.len().min(self.offset+256);for byte in &key.as_bytes()[self.offset..end]{self.hash=(self.hash^u64::from(*byte)).wrapping_mul(1099511628211)}self.offset=end;if end==key.len(){self.slot=self.hash as usize&(self.map.slots().len()-1);self.offset=0;self.phase+=1}}},
 10|13=>{let indexing=self.phase==10;let slots=self.map.slots();if slots.is_vacant(self.slot){if indexing{self.map.insert_vacant(self.slot,self.hash,self.at).map_err(|_|fault())?}self.next_key(if indexing{9}else{12})}else{let(hash,ordinal)=slots.get(self.slot).ok_or_else(fault)?;if *hash==self.hash{self.other=*ordinal;self.phase+=1;self.offset=0}else{self.slot=(self.slot+1)&(slots.len()-1)}}},
 11|14=>{let indexing=self.phase==11;let(a,z)=self.keys(m,b);let end=a.len().min(self.offset+256);if a.len()!=z.len()||a.as_bytes()[self.offset..end]!=z.as_bytes()[self.offset..end]{self.slot=(self.slot+1)&(self.map.slots().len()-1);self.offset=0;self.phase-=1}else if end==a.len(){if indexing||self.new[self.other].from!=NONE{return Err(fault().with_retained_progress(p))}self.new[self.other].from=self.at;self.phase=15}else{self.offset=end}},
 15=>{let(a,z)=self.value_pair(m,b);let step=self.values.advance(a,z,child(g)).map_err(failure)?;p=paid(step.progress);if let Some(equal)=step.equal{self.old[self.at].to=self.other;self.old[self.at].equal=equal;self.new[self.other].equal=equal;self.kept+=usize::from(equal);self.values.begin_rebind().map_err(failure)?;self.phase=16}},
 16=>{let step=self.values.rebind_step(child(g)).map_err(failure)?;p=paid(step.progress());if self.values.ready_to_bind(){self.next_key(12)}},
 17=>if self.at==old{self.at=self.tails.last().copied().unwrap_or(NONE);self.phase=20}else if !self.old[self.at].equal{self.at+=1}else{self.lo=0;self.hi=self.tails.len();self.phase=18},
 18=>if self.lo==self.hi{self.phase=19}else{let mid=self.lo+(self.hi-self.lo)/2;if self.old[self.tails[mid]].to<self.old[self.at].to{self.lo=mid+1}else{self.hi=mid}},
 19=>{self.old[self.at].link=if self.lo==0{NONE}else{self.tails[self.lo-1]};if self.lo==self.tails.len(){self.tails.push(self.at)}else{self.tails[self.lo]=self.at}self.at+=1;self.phase=17},20=>if self.at==NONE{self.phase=21}else{self.old[self.at].keep=true;self.at=self.old[self.at].link},21=>return Ok(RetainedCloneStep::Complete(p)),_=>return Err(fault())}Ok(if self.ready(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 fn next_key(&mut self,phase:u8){self.at+=1;self.offset=0;self.hash=SEED;self.phase=phase}
 pub fn begin_close(&mut self){self.closing=true;self.values.begin_close()}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(fault())}if !self.values.terminal_is_empty(){return Ok(add(self.values.close_demand(body.saturating_sub(Self::FIXED))?))}for(len,capacity,item)in[(self.old.len(),self.old.capacity(),size_of::<Old>()),(self.new.len(),self.new.capacity(),size_of::<New>()),(self.tails.len(),self.tails.capacity(),size_of::<usize>())]{if len>0{return Ok(Self::fixed())}if capacity>0{return Ok(RetirementDemand{release_bytes:capacity*item,..Self::fixed()})}}if self.map.initialized_slots()>0{return Ok(Self::fixed())}if self.map.backing_bytes()>0{return Ok(RetirementDemand{release_bytes:self.map.backing_bytes(),..Self::fixed()})}Ok(add(RetainedCloneBinding::close_demand(if self.b.is_some(){&self.b}else{&self.m},body.saturating_sub(Self::FIXED))?))}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.close_demand(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.values.terminal_is_empty(){return self.values.close_step(child(g)).map(|s|RetainedCloneStep::Progress(paid(s.progress()))).map_err(failure)}let mut p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};if !self.old.is_empty(){self.old.pop();}else if self.old.capacity()>0{p.released_bytes=self.old.capacity()*size_of::<Old>();*self.old=Vec::new()}else if !self.new.is_empty(){self.new.pop();}else if self.new.capacity()>0{p.released_bytes=self.new.capacity()*size_of::<New>();*self.new=Vec::new()}else if !self.tails.is_empty(){self.tails.pop();}else if self.tails.capacity()>0{p.released_bytes=self.tails.capacity()*size_of::<usize>();*self.tails=Vec::new()}else if self.map.pop_last_slot().is_some(){}else if self.map.backing_bytes()>0{p.released_bytes=self.map.release_empty_backing()?}else{let step=RetainedCloneBinding::close_one(if self.b.is_some(){&mut self.b}else{&mut self.m},child(g)).map_err(failure)?;p=paid(step.progress())}Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.values.terminal_is_empty()&&self.old.capacity()==0&&self.new.capacity()==0&&self.tails.capacity()==0&&self.map.backing_bytes()==0&&self.m.is_none()&&self.b.is_none()}
}
impl Drop for DataFieldsPlan{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"data-field plan retains original aliases until funded close")}}
